def find_min_time_to_scare_cities(n, m, roads, attacked):
    # Build the graph
    graph = [[] for _ in range(n + 1)]
    for u, v in roads:
        graph[u].append(v)
        graph[v].append(u)

    # BFS to find the shortest path between two nodes
    def bfs(start, end):
        queue = [(start, 0)]
        visited = set()
        while queue:
            node, dist = queue.pop(0)
            if node == end:
                return dist
            if node not in visited:
                visited.add(node)
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        queue.append((neighbor, dist + 1))
        return float('inf')

    # Find the optimal teleportation point
    best_city = None
    min_time = float('inf')
    for city in attacked:
        total_time = 0
        for other_city in attacked:
            if city != other_city:
                total_time += bfs(city, other_city)
        if total_time < min_time:
            min_time = total_time
            best_city = city

    return best_city, min_time

