from sys import stdin

def read_ints():
    return list(map(int, stdin.readline().split()))

def find_min_time_to_travel(n, m, edges, attacks):
    # Create adjacency list for the graph
    adj_list = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    def bfs(start):
        queue = [(start, 0)]
        visited = set([start])
        while queue:
            current, steps = queue.pop(0)
            if current in attacks:
                return steps
            for neighbor in adj_list[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, steps + 1))
        return float('inf')

    min_time = float('inf')
    best_city = float('inf')
    for city in attacks:
        time = bfs(city)
        if time < min_time or (time == min_time and city < best_city):
            min_time = time
            best_city = city

    return best_city, min_time

